-- Views, each after the views it reads.
CREATE VIEW entities_current AS SELECT entity_key, environment, entity_type, entity_id, state_hash, description, relationships, valid_from_ns, last_seen_ns, last_received_ns, interval_s, deleted_at_ns, delete_reason, wire_form, observer, schema_url, CASE  WHEN ((deleted_at_ns IS NOT NULL)) THEN ('gone') WHEN (((interval_s > 0) AND ((epoch_ns(now()) - last_received_ns) > ((3 * interval_s) * 1000000000)))) THEN ('expired') ELSE 'live' END AS liveness FROM entity_versions QUALIFY (row_number() OVER (PARTITION BY entity_key, environment ORDER BY valid_from_ns DESC) = 1);
CREATE VIEW run_completions AS SELECT ts_ns, log_attrs, log_attrs['experiment_id'] AS experiment_id FROM logs WHERE (body = 'experiment.completed') QUALIFY (row_number() OVER (PARTITION BY log_attrs['experiment_id'] ORDER BY ts_ns DESC) = 1);
CREATE VIEW run_roots AS (SELECT s.ts_ns, s.trace_id, s.span_id, s.parent_span_id, s.span_name, s.span_kind, s.duration_ns, s.status_code, s.status_message, s.service_name, s.service_version, s.experiment_id, s.experiment_name, s.outcome_status, s.fault_type, s.fault_subtype, s.fault_severity, s.blast_radius, s.target_system, s.target_technology, s.target_environment, s.plugin_name, s.hypothesis_met, s.recovery_time_s, s.span_attrs, s.resource_attrs, s.events, false AS journal_only FROM spans AS s WHERE (s.span_name = 'resilience.experiment')) UNION ALL (SELECT e.started_at_ns AS ts_ns, NULL AS trace_id, NULL AS span_id, NULL AS parent_span_id, 'resilience.experiment' AS span_name, 'Internal' AS span_kind, (e.ended_at_ns - e.started_at_ns) AS duration_ns, CASE  WHEN ((lower(e.status) = 'completed')) THEN ('Ok') ELSE 'Error' END AS status_code, '' AS status_message, 'tumult' AS service_name, NULL AS service_version, e.experiment_id, e.title AS experiment_name, lower(e.status) AS outcome_status, NULL AS fault_type, NULL AS fault_subtype, NULL AS fault_severity, NULL AS blast_radius, json_extract_string(g.attrs, '$.target_system') AS target_system, json_extract_string(g.attrs, '$.target_technology') AS target_technology, json_extract_string(g.attrs, '$.target_environment') AS target_environment, NULL AS plugin_name, COALESCE(e.hypothesis_after_met, CASE  WHEN ((NOT e.hypothesis_before_met)) THEN (false) ELSE NULL END) AS hypothesis_met, COALESCE(e.mttr_s, e.rto_measured_s) AS recovery_time_s, NULL AS span_attrs, NULL AS resource_attrs, NULL AS events, true AS journal_only FROM (experiments AS e LEFT JOIN graph_nodes AS g ON ((g.id = ('run:' || e.experiment_id)))) WHERE (NOT EXISTS(SELECT 1 FROM spans AS r WHERE ((r.span_name = 'resilience.experiment') AND (r.experiment_id = e.experiment_id)))));
CREATE VIEW dr_tests AS WITH rto AS (SELECT experiment_id, bool_and(recovered) AS recovered FROM nfr_verdicts WHERE ((kind = 'rto') AND (nfr_id = 'rto')) GROUP BY experiment_id), roots AS (SELECT experiment_id, any_value(target_system) AS target_system, any_value(target_environment) AS target_environment FROM run_roots GROUP BY experiment_id), automated AS (SELECT 'automated' AS origin, e.experiment_id AS evidence_id, e.title AS experiment_name, NULL AS exercise_type, r.target_system, r.target_environment, e.started_at_ns AS executed_at_ns, lower(e.status) AS outcome, e.rto_target_s, COALESCE(e.rto_measured_s, e.mttr_s) AS rto_measured_s, COALESCE(v.recovered, CASE  WHEN ((e.mttr_s IS NOT NULL)) THEN (true) ELSE NULL END) AS recovered, (NOT e.impact_observed) AS no_outage, e.rpo_target_s, e.rpo_measured_s, NULL AS data_verified, NULL AS reviewer, NULL AS plan_id FROM ((experiments AS e LEFT JOIN roots AS r ON ((e.experiment_id = r.experiment_id))) LEFT JOIN rto AS v ON ((e.experiment_id = v.experiment_id))) WHERE (e.test_kind = 'dr')), manual AS (SELECT 'manual' AS origin, m.id AS evidence_id, m.experiment_name, m.exercise_type, m.target_system, m.target_environment, m.executed_at_ns, m.outcome_status AS outcome, m.rto_target_s, m.recovery_time_s AS rto_measured_s, CASE  WHEN ((m.recovery_time_s IS NOT NULL)) THEN (true) ELSE NULL END AS recovered, NULL AS no_outage, m.rpo_target_s, m.rpo_measured_s, m.data_verified, m.reviewed_by AS reviewer, m.plan_id FROM manual_experiments AS m WHERE ((m.status IN ('submitted', 'verified')) AND list_contains(list_value('backup', 'drill', 'failover', 'restore'), m.exercise_type))), tests AS ((SELECT * FROM automated) UNION ALL (SELECT * FROM manual)), judged AS (SELECT *, ((origin || ':') || evidence_id) AS test_id, CASE  WHEN ((NOT recovered)) THEN ('not_recovered') WHEN (((rto_measured_s > rto_target_s) OR (rpo_measured_s > rpo_target_s))) THEN ('breached') WHEN (((COALESCE(rto_target_s, rpo_target_s) IS NOT NULL) AND ((rto_target_s IS NULL) OR (rto_measured_s IS NOT NULL)) AND ((rpo_target_s IS NULL) OR (rpo_measured_s IS NOT NULL)))) THEN ('met') ELSE 'not_measured' END AS verdict FROM tests) SELECT test_id, origin, experiment_name, exercise_type, target_system, target_environment, executed_at_ns, outcome, rto_target_s, rto_measured_s, recovered, no_outage, rpo_target_s, rpo_measured_s, data_verified, verdict, evidence_id, reviewer, plan_id FROM judged;
CREATE VIEW experiment_runs AS SELECT s.experiment_id, any_value(s.experiment_name) AS experiment_name, min(s.ts_ns) AS started_at_ns, max((s.ts_ns + s.duration_ns)) AS ended_at_ns, max(s.duration_ns) AS duration_ns, any_value(lower(COALESCE(s.outcome_status, l.log_attrs['status']))) AS outcome_status, any_value(s.hypothesis_met) AS hypothesis_met FROM (run_roots AS s LEFT JOIN run_completions AS l ON ((s.experiment_id = l.experiment_id))) GROUP BY s.experiment_id;
